-- Effective PostgreSQL contracts, without OIDs, data, secrets or runtime paths.
WITH namespaces AS (SELECT oid,nspname FROM pg_namespace WHERE nspname IN ('public','local_identity','loop_internal'))
SELECT jsonb_build_object(
 'types',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'category',t.typcategory,'element',CASE WHEN t.typelem<>0 THEN (SELECT ns.nspname||'.'||e.typname FROM pg_type e JOIN pg_namespace ns ON ns.oid=e.typnamespace WHERE e.oid=t.typelem) END,'base',CASE WHEN t.typbasetype<>0 THEN (SELECT ns.nspname||'.'||b.typname FROM pg_type b JOIN pg_namespace ns ON ns.oid=b.typnamespace WHERE b.oid=t.typbasetype) END,'enum',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)) ORDER BY n.nspname,t.typname) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('public','local_identity','loop_internal','pg_catalog')),
 'relations',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',tn.nspname||'.'||t.typname,'nullable',NOT a.attnotnull,'default',d.oid IS NOT NULL OR a.attidentity<>'','generated',a.attgenerated<>'' OR a.attidentity='a') ORDER BY a.attnum) FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace tn ON tn.oid=t.typnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'relationships',(SELECT coalesce(jsonb_agg(jsonb_build_object('foreignKeyName',f.conname,'columns',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM unnest(f.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum=k.num),'isOneToOne',EXISTS(SELECT 1 FROM pg_constraint u WHERE u.conrelid=c.oid AND u.contype IN ('p','u') AND u.conkey @> f.conkey AND u.conkey <@ f.conkey),'referencedSchema',rn.nspname,'referencedRelation',r.relname,'referencedColumns',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM unnest(f.confkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum=k.num)) ORDER BY f.conname),'[]') FROM pg_constraint f JOIN pg_class r ON r.oid=f.confrelid JOIN pg_namespace rn ON rn.oid=r.relnamespace WHERE f.conrelid=c.oid AND f.contype='f')) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN namespaces n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p','v','m')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'set',p.proretset,'returnType',rn.nspname||'.'||rt.typname,'args',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',coalesce(p.proargnames[k.i],'arg'||k.i),'mode',coalesce(p.proargmodes[k.i],'i'),'type',an.nspname||'.'||at.typname,'optional',coalesce(p.proargmodes[k.i],'i') IN ('i','b','v') AND (SELECT count(*) FROM generate_series(1,k.i) j WHERE coalesce(p.proargmodes[j],'i') IN ('i','b','v'))>p.pronargs-p.pronargdefaults) ORDER BY k.i),'[]') FROM generate_subscripts(coalesce(p.proallargtypes,p.proargtypes::oid[]),1) original(sub) CROSS JOIN LATERAL (SELECT CASE WHEN p.proallargtypes IS NULL THEN original.sub+1 ELSE original.sub END i)k JOIN pg_type at ON at.oid=coalesce(p.proallargtypes[k.i],p.proargtypes[k.i-1]) JOIN pg_namespace an ON an.oid=at.typnamespace)) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN namespaces n ON n.oid=p.pronamespace JOIN pg_type rt ON rt.oid=p.prorettype JOIN pg_namespace rn ON rn.oid=rt.typnamespace WHERE p.prokind='f' AND rt.typname NOT IN ('trigger','event_trigger') AND (has_function_privilege('loop_app',p.oid,'EXECUTE') OR has_function_privilege('loop_worker',p.oid,'EXECUTE') OR has_function_privilege('loop_owner',p.oid,'EXECUTE')))
);
